std::string trimHTMLstr(std::string str)
{
	char * HTML[5][2] = {
		{"&lt;",   "<"},
		{"&gt;",   ">"},
		{"&amp;",  "&"},
		{"&quot;", "\""},
		{"&apos;", "\'"},
	};

	for(int i = 0; i < 5; i++)
	{
		int pos = -1;
		while((pos = str.find(HTML[i][0])) >= 0)
			str.replace(pos, strlen(HTML[i][0]), HTML[i][1]);
	}

	int begin = 0;
	while((begin = str.find("<", begin)) >= 0)
	{
		int end = str.find(">", begin);
		if(end == -1)
			end = str.length();
		str.erase(begin, end + 1);
	}

	return str;
}
